const escoGraphTableNames=Object.keys(escoGraphColumns).sort()
function escoGraphRequire(condition:unknown,reason:string):asserts condition{
 if(!condition)throw Error(`esco_private_graph_${reason}`)
}
function escoGraphRecord(value:unknown):value is Record<string,unknown>{
 return value!==null&&typeof value==='object'&&!Array.isArray(value)&&(Object.getPrototypeOf(value)===Object.prototype||Object.getPrototypeOf(value)===null)
}
function escoGraphSameKeys(value:unknown,names:readonly string[],reason:string):asserts value is Record<string,unknown>{
 escoGraphRequire(escoGraphRecord(value),reason)
 escoGraphRequire(JSON.stringify(Object.keys(value).sort())===JSON.stringify([...names].sort()),reason)
}
function escoGraphJson(value:unknown,ancestors=new Set<object>()):string{
 if(value===null||typeof value==='string'||typeof value==='boolean')return JSON.stringify(value)
 if(typeof value==='number'){escoGraphRequire(Number.isFinite(value),'non_json_number');return JSON.stringify(value)}
 escoGraphRequire(Array.isArray(value)||escoGraphRecord(value),'non_json_value')
 escoGraphRequire(!ancestors.has(value),'cyclic_json');ancestors.add(value)
 let text:string
 if(Array.isArray(value)){
  escoGraphRequire(Object.keys(value).length===value.length&&Reflect.ownKeys(value).length===value.length+1,'sparse_or_extra_array')
  text='['+value.map(item=>escoGraphJson(item,ancestors)).join(',')+']'
 }else{
  escoGraphRequire(Reflect.ownKeys(value).length===Object.keys(value).length,'non_json_property')
  text='{'+Object.keys(value).sort().map(key=>JSON.stringify(key)+':'+escoGraphJson(value[key],ancestors)).join(',')+'}'
 }
 ancestors.delete(value);return text
}
function escoGraphRows(table:string,value:unknown):asserts value is EscoGraphRow[]{
 escoGraphRequire(Array.isArray(value),'rows_required');const ids=new Set<string>()
 for(const row of value){
  escoGraphSameKeys(row,escoGraphColumns[table],'whole_row_columns');escoGraphJson(row)
  const key=escoGraphKeys[table].map(name=>{escoGraphRequire(row[name]!==null,'primary_key_null');return row[name]})
  const id=escoGraphJson(key);escoGraphRequire(!ids.has(id),'duplicate_primary_key');ids.add(id)
 }
}
function escoGraphValidate(value:unknown):asserts value is EscoNationalPrivateGraphFrame{
 escoGraphSameKeys(value,['version','schema','tables'],'frame_shape');escoGraphRequire(value.version===1,'frame_version')
 escoGraphSameKeys(value.schema,escoGraphTableNames,'schema_tables');escoGraphSameKeys(value.tables,escoGraphTableNames,'row_tables')
 for(const table of escoGraphTableNames){
  const descriptors=value.schema[table];escoGraphRequire(Array.isArray(descriptors),'descriptors_required')
  escoGraphRequire(descriptors.length===escoGraphColumns[table].length,'descriptor_census')
  let position=0
  for(let index=0;index<descriptors.length;index++){
   const descriptor=descriptors[index];escoGraphSameKeys(descriptor,['name','position','type','notNull','default','generated'],'descriptor_shape')
   escoGraphRequire(descriptor.name===escoGraphColumns[table][index],'descriptor_name')
   escoGraphRequire(Number.isSafeInteger(descriptor.position)&&Number(descriptor.position)>position,'descriptor_position');position=Number(descriptor.position)
   escoGraphRequire(typeof descriptor.type==='string'&&descriptor.type.length>0&&typeof descriptor.notNull==='boolean','descriptor_type')
   escoGraphRequire(descriptor.default===null||typeof descriptor.default==='string','descriptor_default')
   escoGraphRequire(descriptor.generated===''||descriptor.generated==='s'||descriptor.generated==='v','descriptor_generated')
  }
  escoGraphRows(table,value.tables[table])
  for(const row of value.tables[table])for(const descriptor of descriptors)escoGraphRequire(!descriptor.notNull||row[descriptor.name]!==null,'nonnull_row')
 }
 escoGraphJson(value)
}
