const escoMailReadQuery='SELECT jsonb_build_object(\'version\',1,\'schema\',(SELECT jsonb_object_agg(x.name,x.value) FROM (VALUES '+
 escoMailNames.map(table=>`('${table}',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'position',a.attnum,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid),'generated',a.attgenerated) ORDER BY a.attnum),'[]'::jsonb) FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=pg_catalog.to_regclass('${table}') AND a.attnum>0 AND NOT a.attisdropped))`).join(',')+
 ')x(name,value)),\'tables\',(SELECT jsonb_object_agg(x.name,x.value) FROM (VALUES '+escoMailNames.map(table=>`('${table}',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM ${table} t))`).join(',')+')x(name,value)))'
