export function captureEscoNationalWholeBirthFrame(read:<T>(query:string)=>T){const actual=read<unknown>(escoMailReadQuery);escoMailValidate(actual);const before=structuredClone(actual)
 return {snapshot:()=>structuredClone(before),qualify(expectedRowsByTable:Record<string,EscoGraphRow[]>){escoGraphRequire(escoGraphRecord(expectedRowsByTable),'mail_expected_map');for(const t of Object.keys(expectedRowsByTable))escoGraphRequire(escoMailNames.includes(t),'mail_expected_table');const expected=structuredClone(expectedRowsByTable),post=read<unknown>(escoMailReadQuery);escoMailValidate(post);escoGraphRequire(escoGraphJson(post.schema)===escoGraphJson(before.schema),'mail_schema_changed');for(const t of escoMailNames)escoMailEqualRows(post.tables[t],expected[t]??before.tables[t],t)}}
}
function escoMailEqualRows(actual:EscoGraphRow[],wanted:EscoGraphRow[],table:string){escoGraphRequire(JSON.stringify(actual.map(r=>escoGraphJson(r)).sort())===JSON.stringify(wanted.map(r=>escoGraphJson(r)).sort()),'mail_whole_row:'+table)}
