 const priorIds=new Set<string>();const collect=(v:unknown):void=>{if(typeof v==='string'&&escoCanonicalUuid.test(v))priorIds.add(v);else if(Array.isArray(v))v.forEach(collect);else if(escoGraphRecord(v))Object.values(v).forEach(collect)};collect(before.tables);priorIds.add(basis.companyId)
