 function checked(current:EscoNationalPrivateGraphFrame,window:EscoMailWindow){escoMailValidate(current);escoGraphRequire(escoGraphJson(current.schema)===escoGraphJson(before.schema),'mail_schema_changed');const a=escoCanonicalInstant(window.startedAt),b=escoCanonicalInstant(window.finishedAt);escoGraphRequire(b>=a&&b-a<=BigInt(120000000),'mail_window');return(v:unknown)=>{const t=escoCanonicalInstant(v);escoGraphRequire(t>=a&&t<=b,'mail_clock');return v as string}}
 function fresh(v:unknown,current:EscoNationalPrivateGraphFrame,used:Set<string>){escoGraphRequire(typeof v==='string'&&escoCanonicalUuid.test(v)&&!priorIds.has(v)&&!used.has(v),'mail_fresh_id');escoGraphRequire(Object.values(current.tables).flat().filter(r=>r.id===v).length===1,'mail_global_id');used.add(v as string);return v as string}
 function added(current:EscoNationalPrivateGraphFrame,base:EscoNationalPrivateGraphFrame,t:string,count:number){const old=base.tables[t],held=new Set(old.map(r=>escoGraphJson(r)));const rows=current.tables[t].filter(r=>!held.has(escoGraphJson(r)));escoGraphRequire(current.tables[t].length===old.length+count&&rows.length===count,'mail_count:'+t);for(const r of old)escoGraphRequire(current.tables[t].some(x=>escoGraphJson(x)===escoGraphJson(r)),'mail_old:'+t);return rows}
